    //   j <  i :  (-j % n) / n + 1
    //   j == i :  1
    //   j >  i :  0
    // ------------------------------------------------------------------

    // We keep this temporary separate from the final A so that the
    // subsequent A * A^T step can safely read from it while writing
    // into A.
    Halide::Buffer<num_t, 2> A_tri(n, n);

    Func init_tri("init_tri");

    // base = (DATA_TYPE)(-j % n) / n + 1;
    Expr base = cast<num_t>(-(j % n));
    base = base / cast<num_t>(n) + cast<num_t>(1);

    // Piecewise definition that exactly matches the C initialization.
    init_tri(j, i) =
        select(j < i, base,           // below diagonal
               select(j == i,
                      cast<num_t>(1), // diagonal
                      cast<num_t>(0)  // above diagonal
                      ));

    // Schedule for init_tri:
    //  - parallelize over rows (i)
    //  - vectorize over contiguous columns (j)
    init_tri
        .compute_root()
        .parallel(i)
        .vectorize(j, 8);  // 8-wide vectors (works well for typical float/double)

    // Realize triangular matrix into A_tri.
    init_tri.realize(A_tri);

    // ------------------------------------------------------------------
    // 2) Make the matrix positive semi-definite: B = A * A^T
    //
    // Original C:
    //
    // for (r = 0; r < n; ++r)
    //   for (s = 0; s < n; ++s) {
    //     B[r][s] = 0;
    //     for (t = 0; t < n; ++t)
    //       B[r][s] += A[r][t] * A[s][t];
    //   }
    // A[r][s] = B[r][s];
    //
    // With our mapping A(j, i) == A[i][j], we want:
    //   B[r][s] = sum_t A_tri[r][t] * A_tri[s][t]
    //   => B(s, r) = sum_t A_tri(t, r) * A_tri(t, s)
    //
    // We implement B(s, r) as a Halide reduction and realize it
    // directly into the final buffer A.
    // ------------------------------------------------------------------

    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    A_param.set(A_tri);

    Var r("r"), s("s");
    RDom t(0, n, "t");

    Func B_func("B_func");

    // Pure definition: initialize to zero.
    B_func(s, r) = cast<num_t>(0);

    // Reduction update: accumulate A_tri[r][t] * A_tri[s][t]
    // i.e. A_param(t, r) * A_param(t, s) under our layout.
    B_func(s, r) += A_param(t, r) * A_param(t, s);

    // Schedule for B_func:
    //  - compute at root
    //  - parallelize across rows (r)
    //  - vectorize across contiguous columns (s)
    //
    // For the update step, reorder loops so that:
    //   for r (parallel)
    //     for t
    //       for s (vectorized)
    //
    // This gives good data locality and exploits SIMD on s.
    const int vec = 8;  // fixed SIMD width; works well for typical float/double
    B_func
        .compute_root()
        .parallel(r)
        .vectorize(s, vec);

    B_func.update()
        .reorder(s, t, r)
        .parallel(r)
        .vectorize(s, vec);

    // Realize B_func directly into A; this writes the final SPD
    // matrix into A without an intermediate copy.
    B_func.realize(A);
}

