            }
            A(j, i) -= accum;
            A(j, i) /= A(j, j);
        }

        // Diagonal element.
        num_t accum = static_cast<num_t>(0);
        for (int k = 0; k < i; k++) {
            accum += A(k, i) * A(k, i);
        }
        A(i, i) -= accum;
        A(i, i) = static_cast<num_t>(std::sqrt(static_cast<double>(A(i, i))));
