#include "cholesky.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

// Initialize matrix A as in the original Polybench C code, but using
// a Halide pipeline with an optimized schedule.
//
// The matrix is stored as A(j, i) == A[i][j] from the original C code.
//
// 1) First we construct a lower-triangular matrix L with diagonal 1.
// 2) Then we form A = L * L^T, which is symmetric positive semi-definite.
static void init_array(int n, Halide::Buffer<num_t, 2> A) {
    Var i("i"), j("j");

    // Lower-triangular matrix with diagonal ones:
    //
    // for (i = 0; i < n; i++) {
    //   for (j = 0; j <= i; j++)
    //     A[i][j] = (DATA_TYPE)(-j % n) / n + 1;
    //   for (j = i+1; j < n; j++)
    //     A[i][j] = 0;
    //   A[i][i] = 1;
    // }
    //
    // Mapping: L(j, i) == A[i][j].
    Func lower("lower");

    Expr val = cast<num_t>(-(j % n));
    val = val / cast<num_t>(n) + cast<num_t>(1);

    // Fill strictly lower & diagonal.
    lower(j, i) = select(j <= i, val, cast<num_t>(0));
    // Explicit diagonal ones.
    lower(i, i) = cast<num_t>(1);

    // Form A = L * L^T.
    Var r("r"), s("s");
    RDom t(0, n, "t");

    Func A_spd("A_spd");
    A_spd(s, r) = cast<num_t>(0);
    A_spd(s, r) += lower(t, r) * lower(t, s);

    // ------------------------------------------------------------------
    // Scheduling: compute lower once, then A_spd in a cache-friendly way.
    // ------------------------------------------------------------------
    // Compute the lower-triangular matrix explicitly.
    lower.compute_root()
        .parallel(i)      // parallelize over rows
        .vectorize(j, 4); // and vectorize over columns

    // Compute A_spd at root, parallelizing over rows and vectorizing over cols.
    A_spd.compute_root()
        .parallel(r)
        .vectorize(s, 4);

    // Realize the positive semi-definite matrix directly into A.
    Target target = get_host_target();
    A_spd.realize(A, target);
}

int main(int argc, char *argv[]) {
    // Problem size.
    int n = N;

    // Matrix A, using Halide::Buffer.
    // We follow the convention: A(j, i) == A[i][j] from the original C.
    Halide::Buffer<num_t, 2> A(n, n);

    // Initialize A as in the original Polybench code (SPD matrix).
    init_array(n, A);

    // ------------------------------------------------------------------
    // Build a Halide pipeline for the Cholesky factorization.
    //
    // We use a mathematically equivalent column-wise algorithm:
    //
    // for (j = 0; j < n; j++) {
    //   // Diagonal element L[j][j]
    //   for (k = 0; k < j; k++)
    //     A[j][j] -= A[j][k] * A[j][k];
    //   A[j][j] = sqrt(A[j][j]);
    //
    //   // Below-diagonal elements in column j
    //   for (i = j+1; i < n; i++) {
    //     for (k = 0; k < j; k++)
    //       A[i][j] -= A[i][k] * A[j][k];
    //     A[i][j] /= A[j][j];
    //   }
    // }
    //
    // With mapping A(j, i) == A[i][j] (col, row):
    //   A[j][j]   -> A(j, j)
    //   A[i][j]   -> A(j, i)
    //   A[i][k]   -> A(k, i)
    //   A[j][k]   -> A(k, j)
    //
    // This algorithm depends only on previously computed columns, so for
    // a fixed column j we can compute the entire column from the current
    // matrix state without intra-column dependencies. We orchestrate the
    // sequential outer loop over j in C++, and express the inner sums
    // over k as Halide reductions. This respects Halide’s restriction
    // against self-referential updates at different coordinates.
    // ------------------------------------------------------------------

    // ImageParam for the current matrix A (read-only view).
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    A_param.set(A);

    // Column index j is a runtime parameter.
    Param<int> j_param("j");

    // Row index for 1D vector computations (rows of a given column j).
    Var r("r");

    // ---------------------------
    // Diagonal element L(j, j).
    // ---------------------------
    //
    // diag_val(j) = sqrt( A(j, j) - sum_{k=0}^{j-1} A(k, j)^2 )
    //
    // We implement this as a 1D Func of length 1 (index 'dummy') so that
    // we can easily realize it into a 1-element buffer and reuse across
    // off-diagonal computations.
    Var dummy("dummy");
    RDom k_diag(0, j_param, "k_diag");

    Func diag("chol_diag");
    {
        // sum_k A(k, j)^2
        Expr diag_sum = sum(A_param(k_diag, j_param) * A_param(k_diag, j_param));
        Expr base = A_param(j_param, j_param) - diag_sum;
        diag(dummy) = sqrt(base);
    }

    // --------------------------------------
    // Off-diagonal numerators for column j.
    // --------------------------------------
    //
    // For each row r, compute:
    //   numer(r) = A(j, r) - sum_{k=0}^{j-1} A(k, r) * A(k, j)
    //
    // For r > j, we will later divide by diag(j) in C++:
    //   L(r, j) = numer(r) / diag(j)
    //
    // Mapping to buffer indices (col, row):
    //   A(j, r) is the SPD entry M[r][j].
    //   A(k, r) = L[r][k] for k < j (already computed).
    //   A(k, j) = L[j][k].
    RDom k_off(0, j_param, "k_off");

    Func col_numer("chol_col_numer");
    {
        Expr dot = sum(A_param(k_off, r) * A_param(k_off, j_param));
        col_numer(r) = A_param(j_param, r) - dot;
    }

    // -----------------
    // Scheduling hints.
    // -----------------
    //
    // We compile these pipelines once and reuse them for each j.
    // For diag we just compute a single scalar; for col_numer we
    // compute a length-n vector, parallelizing and vectorizing over r.
    Target target = get_host_target();

    // Diagonal is a tiny reduction; compute it at root.
    diag.compute_root();

    // For col_numer, compute at root, parallelize across chunks of rows
    // and vectorize within each chunk for good memory locality.
    Var ro("ro"), ri("ri");
    const int vec = 4; // reasonable default for modern x86 (4 doubles or 4 floats)

    col_numer
        .compute_root()
        .split(r, ro, ri, vec)
        .parallel(ro)
        .vectorize(ri);

    // Pre-JIT compile to exclude compilation time from the timed region.
    diag.compile_jit(target);
    col_numer.compile_jit(target);

    // Pre-allocate buffer for column numerators; we reuse it for every j.
    Halide::Buffer<num_t> col_buf(n);

    // -------------------------------
    // Time the Cholesky factorization
    // -------------------------------
    auto start = std::chrono::high_resolution_clock::now();

    // Sequential outer loop over columns. Inside, all heavy computation
    // (the k-sums) is performed via Halide pipelines; we only do simple
    // scalar divisions and stores on the host.
    for (int j = 0; j < n; ++j) {
        j_param.set(j);

        // 1) Compute diagonal L(j, j).
        Halide::Buffer<num_t> diag_buf(1);
        diag.realize(diag_buf, target);
        num_t diag_val = diag_buf(0);

        // Write back the diagonal element.
        A(j, j) = diag_val;

        // 2) Compute numerators for the entire column j.
        //
        // We compute for all rows r in [0, n), but will only use the
        // entries with r > j. Computing extra rows keeps the Halide
        // code simple and does not change the asymptotic complexity
        // (still O(n^3)).
        col_numer.realize(col_buf, target);

        // 3) Update entries below the diagonal for column j.
        for (int i = j + 1; i < n; ++i) {
            A(j, i) = col_buf(i) / diag_val;
        }
        // Entries above the diagonal (i <= j) are never read by the
        // algorithm and can remain as-is.
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the resulting lower-triangular matrix A,
    // similar to Polybench's print_array (only j <= i).
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j <= i; j++) {
                std::cerr << A(j, i) << '\n';
            }
        }
    }

    // Print elapsed time in seconds.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
