#include <cmath>
#include <iomanip>
#include <iostream>

#include "Halide.h"

// include common Polybench-style definitions (DATA_TYPE, N, etc.)
#include "defines.hpp"

// include benchmark-specific definitions for cholesky (DATA_TYPE, N, etc.)
#include "cholesky.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

// Initialize matrix A as in the original Polybench C code, but do it
// as a single optimized Halide pipeline.
//
// Original C (conceptually):
//   1) Build a lower-triangular matrix L with diagonal 1.
//   2) Form B = L * L^T.
//   3) Copy B back into A.
//
// Here we express L and B in Halide. We never materialize L in a
// separate buffer: B is computed directly from the definition of L.
// The final Buffer A holds B, which is exactly what the C code
// produces (up to floating-point roundoff).
static void init_array(int n, Halide::Buffer<num_t, 2> A) {
    // A(x, y) corresponds to C's A[y][x].
    Var x("x"), y("y");

    // Step 1: define the lower-triangular matrix L (called A_tri here).
    //
    // C code:
    //   for (i = 0; i < n; i++) {
    //     for (j = 0; j <= i; j++)
    //       A[i][j] = (DATA_TYPE)(-j % n) / n + 1;
    //     for (j = i+1; j < n; j++)
    //       A[i][j] = 0;
    //     A[i][i] = 1;
    //   }
    //
    // Mapping: A[i][j] -> A(j, i).
    // L(j, i) = f(j) for j < i, L(i, i) = 1, and 0 for j > i.
    Func A_tri("A_tri");

    Expr n_expr = Expr(n);
    Expr val = cast<num_t>(-(x % n_expr));
    val = val / cast<num_t>(n_expr) + cast<num_t>(1);

    // Lower triangular (including diagonal) gets 'val', above-diagonal is 0.
    A_tri(x, y) = select(x <= y, val, cast<num_t>(0));
    // Explicitly force the diagonal to 1, as in the C code.
    A_tri(x, x) = cast<num_t>(1);

    // Step 2: form B = L * L^T.
    //
    // C code for B:
    //   for (r = 0; r < n; ++r)
    //     for (s = 0; s < n; ++s) {
    //       B[r][s] = 0;
    //       for (t = 0; t < n; ++t)
    //         B[r][s] += A[r][t] * A[s][t];
    //     }
    //
    // Mapping B[r][s] -> PSD(s, r) with L defined above.
    Func PSD("PSD");
    RDom t(0, n, "t");

    PSD(x, y) = cast<num_t>(0);
    PSD(x, y) += A_tri(t, y) * A_tri(t, x);

    // ------------------ Scheduling for init_array ------------------
    //
    // Goal: Good cache locality and use of SIMD.
    //
    //  - x is the fastest-varying dimension in the Buffer, so we
    //    vectorize along x.
    //  - We tile the output and parallelize over tile rows (yo).
    //
    Var xo("xo"), yo("yo"), xi("xi"), yi("yi");
    Target target = get_host_target();
    int vec_width = target.natural_vector_size(type_of<num_t>());
    if (vec_width < 1) {
        vec_width = 1;
    }

    PSD.compute_root()
       .tile(x, y, xo, yo, xi, yi, 16, 16)
       .vectorize(xi, vec_width)
       .parallel(yo);

    // A is the final positive semi-definite matrix.
    PSD.realize(A);
}

int main(int argc, char *argv[]) {
    // Problem size.
    int n = N;

    // Matrix A, using Halide::Buffer.
    // We follow the convention: A(j, i) == A[i][j] from the original C.
    Halide::Buffer<num_t, 2> A(n, n);

    // Initialize A as in the original Polybench code
    // (lower-triangular L, then A = L * L^T), but via an optimized
    // Halide pipeline.
    init_array(n, A);

    // Time the Cholesky factorization kernel (still expressed as
    // straightforward C++ loops; the timing harness is unchanged).
    auto start = std::chrono::high_resolution_clock::now();

    // Main computational kernel translated directly, operating on the Buffer.
    //
    // Original C:
    //
    // for (i = 0; i < _PB_N; i++) {
    //   // j < i
    //   for (j = 0; j < i; j++) {
    //     for (k = 0; k < j; k++) {
    //       A[i][j] -= A[i][k] * A[j][k];
    //     }
    //     A[i][j] /= A[j][j];
    //   }
    //   // i == j case
    //   for (k = 0; k < i; k++) {
    //     A[i][i] -= A[i][k] * A[i][k];
    //   }
    //   A[i][i] = SQRT_FUN(A[i][i]);
    // }
    //
    // With mapping A(j, i) == A[i][j]:
    //   A[i][j]   -> A(j, i)
    //   A[i][k]   -> A(k, i)
    //   A[j][k]   -> A(k, j)
    //   A[j][j]   -> A(j, j)
    //   A[i][i]   -> A(i, i)
    //
    for (int i = 0; i < n; i++) {
        // Off-diagonal elements in row i.
        for (int j = 0; j < i; j++) {
            for (int k = 0; k < j; k++) {
                A(j, i) -= A(k, i) * A(k, j);
            }
            A(j, i) /= A(j, j);
        }

        // Diagonal element.
        for (int k = 0; k < i; k++) {
            A(i, i) -= A(k, i) * A(k, i);
        }
        A(i, i) = static_cast<num_t>(std::sqrt(static_cast<double>(A(i, i))));
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the resulting lower-triangular matrix A,
    // similar to Polybench's print_array (only j <= i).
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
