// In this file, the Halide Buffer has layout A(col, row) == A[i][j] from C.
// We construct the same L and then compute A = L * L^T directly into A.
static void init_array(int n, Halide::Buffer<num_t, 2> A) {
    // Indices:
    //   r = row index i
    //   s = column index j
    Var s("s"), r("r");

    // Step 1: define the lower-triangular matrix L(s, r)
    // corresponding to A[i][j] in the Polybench code.
    //
    // L(r, s) == A[i][j] with mapping:
    //   row i -> r  (second dimension of Buffer)
    //   col j -> s  (first dimension of Buffer)
    //
    // Original C formula for j <= i:
    //   A[i][j] = (-j % n) / n + 1;
    Func L("L");

    Expr base = cast<num_t>(-(s % n));
    base = base / cast<num_t>(n) + cast<num_t>(1);

    // Below or on the diagonal: base value; strictly above: 0.
    L(s, r) = select(s <= r, base, cast<num_t>(0));

    // Explicitly set the diagonal to 1 to match the C code.
    L(r, r) = cast<num_t>(1);

    // Step 2: A = L * L^T
    //
    // Original C:
    //   B[r][s] = 0;
    //   for (t = 0; t < n; ++t)
    //     B[r][s] += A[r][t] * A[s][t];
    //   A[r][s] = B[r][s];
    //
    // With our mapping, this is:
    //   A(s, r) = sum_t L(t, r) * L(t, s);
    RDom t(0, n, "t");

    Func SPD("SPD");
    SPD(s, r) = cast<num_t>(0);
    SPD(s, r) += L(t, r) * L(t, s);

    // --------- Scheduling for better locality and throughput ---------
    //
    // We compute SPD at the root and exploit:
    //   - parallelism across rows (r dimension),
    //   - vectorization across columns (s dimension), which are
    //     contiguous in memory for Halide::Buffer.
    Target target = get_host_target();
    const int vec = target.natural_vector_size(type_of<num_t>());

    // Pure definition: parallelize across rows, vectorize across columns.
    SPD.compute_root()
        .parallel(r)
        .vectorize(s, vec);

    // Update (reduction) step: use the same mapping.
    SPD.update()
        .parallel(r)
        .vectorize(s, vec);
    // -----------------------------------------------------------------

    // Realize directly into the provided Buffer A.
    // This produces exactly the same SPD matrix as the original
    // init_array (lower-triangular L followed by B = L * L^T).
    SPD.realize(A);
}

int main(int argc, char *argv[]) {
    // Problem size.
    int n = N;

    // Matrix A, using Halide::Buffer.
    // We follow the convention: A(j, i) == A[i][j] from the original C.
    Halide::Buffer<num_t, 2> A(n, n);

    // Initialize A as in the original Polybench code, using the
    // optimized Halide pipeline above.
    init_array(n, A);

    // Time the Cholesky factorization kernel.
    auto start = std::chrono::high_resolution_clock::now();

    // Main computational kernel translated directly, operating on the Buffer.
    //
    // Original C:
    //
    // for (i = 0; i < _PB_N; i++) {
    //   // j < i
    //   for (j = 0; j < i; j++) {
    //     for (k = 0; k < j; k++) {
    //       A[i][j] -= A[i][k] * A[j][k];
    //     }
    //     A[i][j] /= A[j][j];
    //   }
    //   // i == j case
    //   for (k = 0; k < i; k++) {
    //     A[i][i] -= A[i][k] * A[i][k];
    //   }
    //   A[i][i] = SQRT_FUN(A[i][i]);
    // }
    //
    // With mapping A(j, i) == A[i][j]:
    //   A[i][j]   -> A(j, i)
    //   A[i][k]   -> A(k, i)
    //   A[j][k]   -> A(k, j)
    //   A[j][j]   -> A(j, j)
    //   A[i][i]   -> A(i, i)
    //
    // This algorithm has strong loop-carried dependencies across i and
    // j and across entries within a row (each A[i][j] uses earlier
    // A[i][k] in the same row). Because of those dependencies, it is
    // not naturally expressible as a single pure Halide Func over all
    // (i, j) without introducing illegal self-referential updates.
    // We therefore keep the factorization itself as a straightforward
    // scalar loop nest, while using Halide for the heavy SPD
    // initialization above.
    for (int i = 0; i < n; i++) {
        // Off-diagonal elements in row i.
        for (int j = 0; j < i; j++) {
            for (int k = 0; k < j; k++) {
                A(j, i) -= A(k, i) * A(k, j);
            }
            A(j, i) /= A(j, j);
        }

        // Diagonal element.
        for (int k = 0; k < i; k++) {
            A(i, i) -= A(k, i) * A(k, i);
        }
        A(i, i) = static_cast<num_t>(std::sqrt(static_cast<double>(A(i, i))));
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the resulting lower-triangular matrix A,
    // similar to Polybench's print_array (only j <= i).
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j <= i; j++) {
                std::cerr << A(j, i) << '\n';
            }
        }
    }

    // Print elapsed time in seconds.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
