    // 5. Realize directly into A
    // ----------------------------------------------------------
    //
    // B_func(s, r) is B[r][s] in C indexing, so A(s, r) == A[i][j]
    // will contain the SPD matrix as required:
    //
    //   A[i][j] = B[i][j] = sum_t L[i][t] * L[j][t]
    //
    // No extra copying is needed.
    B_func.realize(A);
}

